#!/usr/bin/env python3
"""Render the static public paper from aggregate-only capstone results."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RESULTS = json.loads((ROOT / "work" / "results.json").read_text(encoding="utf-8"))
D = RESULTS["dataset"]
A = RESULTS["analysis"]
fmt = lambda x, n=3: f"{x:,.{n}f}"
pct_change = fmt(A["mae_improvement_vs_baseline_pct"], 1)
recs = A["ranked_aggregate_recommendations"][:6]
rows = "\n".join(
    "<tr>"
    f"<td>{html.escape(r['content_type'])}</td>"
    f"<td>{html.escape(r['main_intent'] if r['main_intent'] != 'nan' else 'Not classified')}</td>"
    f"<td>{html.escape(r['position_tier'].replace('_', ' '))}</td>"
    f"<td>{r['eligible_pages']:,}</td>"
    f"<td>{fmt(r['observed_ctr_pct'], 3)}%</td>"
    f"<td>{fmt(r['expected_ctr_pct'], 3)}%</td>"
    f"<td>{r['positive_gap_click_proxy']:,.0f}</td>"
    "</tr>"
    for r in recs
)

abstract = (
    "This study asks whether page and search-context fields can estimate same-window click-through rate (CTR) "
    "and support review prioritization in anonymized content-performance data. We use FlyRank’s public "
    "30,000-row starter release, define CTR over the latest 30-day window, and restrict evaluation to pages "
    "with at least 50 impressions. A position-tier weighted-mean baseline is compared with a random-forest "
    "regressor using five client-grouped folds and no client/page identifiers or outcome-derived feature fields. "
    f"The model’s impression-weighted MAE is {fmt(A['model_weighted_mae_pp'], 3)} percentage points versus "
    f"{fmt(A['baseline_weighted_mae_pp'], 3)} for the baseline ({pct_change}% lower), with performance varying "
    "across held-out folds. The ranked cohorts are descriptive decision support—not a forecast, causal estimate, "
    "or guaranteed click uplift—and identify groups where aggregate observed CTR is below model expectation."
)

page = f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="A client-grouped validation study of CTR review prioritization using the public FlyRank anonymized starter dataset.">
<title>Finding the pages worth a closer look | Search Intelligence Capstone</title>
<style>
:root{{--ink:#172b34;--muted:#566b73;--paper:#f5f6f3;--card:#fff;--teal:#276968;--gold:#d58f48;--line:#d9e0dd;--wash:#e8efec}}
*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--paper);color:var(--ink);font:16px/1.68 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}}
a{{color:var(--teal);text-underline-offset:3px}}.hero{{background:#173a40;color:#f7f7f2;padding:72px max(24px,calc((100vw - 1080px)/2)) 62px}}.eyebrow{{text-transform:uppercase;letter-spacing:.14em;color:#a9cebf;font-size:.77rem;font-weight:700}}h1{{max-width:850px;font:600 clamp(2.4rem,6vw,4.6rem)/1.05 Georgia,serif;letter-spacing:-.035em;margin:.5rem 0 1rem}}.dek{{max-width:720px;color:#d5e0db;font-size:1.13rem;margin:0}}.meta{{margin-top:26px;font-size:.9rem;color:#b7ccc4}}main{{max-width:1080px;margin:auto;padding:36px 24px 80px}}nav{{display:flex;flex-wrap:wrap;gap:10px 22px;padding:15px 0 25px;border-bottom:1px solid var(--line);font-size:.9rem}}nav a{{text-decoration:none}}section{{padding:38px 0;border-bottom:1px solid var(--line)}}h2{{font:600 2rem/1.2 Georgia,serif;letter-spacing:-.02em;margin:0 0 17px}}h3{{font-size:1.1rem;margin:25px 0 8px}}.abstract{{font:1.08rem/1.78 Georgia,serif;max-width:850px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}}.stat,.card{{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px}}.stat b{{display:block;font:600 1.8rem Georgia,serif;color:var(--teal)}}.stat span{{font-size:.86rem;color:var(--muted)}}.callout{{background:var(--wash);border-left:4px solid var(--teal);padding:15px 18px;border-radius:0 10px 10px 0;margin:20px 0}}.figure{{background:#fff;padding:14px;border:1px solid var(--line);border-radius:14px;margin:20px 0}}.figure img{{width:100%;height:auto;display:block}}.caption{{font-size:.87rem;color:var(--muted);margin:8px 5px 2px}}.twocol{{display:grid;grid-template-columns:1fr 1fr;gap:22px}}table{{border-collapse:collapse;width:100%;font-size:.91rem;background:#fff;border-radius:12px;overflow:hidden}}th,td{{padding:11px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}}th{{background:#e7efeb;font-size:.8rem;text-transform:uppercase;letter-spacing:.04em}}td:nth-child(n+4){{font-variant-numeric:tabular-nums}}.table-wrap{{overflow-x:auto;border:1px solid var(--line);border-radius:12px}}.small{{font-size:.9rem;color:var(--muted)}}.method-list li{{margin:.45rem 0}}footer{{padding:28px 0 0;color:var(--muted);font-size:.9rem}}.links a{{margin-right:16px}}@media(max-width:700px){{.hero{{padding:52px 22px 42px}}main{{padding:20px 18px 60px}}.grid{{grid-template-columns:1fr}}.twocol{{grid-template-columns:1fr}}h2{{font-size:1.7rem}}table{{min-width:780px}}}}
</style>
</head>
<body>
<header class="hero"><div class="eyebrow">Search Intelligence · Capstone Research</div>
<h1>Finding the pages worth a closer look</h1>
<p class="dek">A client-held-out study of CTR review prioritization using anonymized content-performance data. The result is a modest modelling gain—and a cautious, aggregate action list.</p>
<div class="meta">Analysis date: 17 October 2026 · Dataset: public FlyRank starter release · Decision-support study</div></header>
<main>
<nav aria-label="Paper sections"><a href="#abstract">Abstract</a><a href="#problem">Problem</a><a href="#data">Data</a><a href="#method">Method</a><a href="#results">Results</a><a href="#limitations">Limitations</a><a href="#recommendations">Recommendations</a><a href="#reproducibility">Reproducibility</a></nav>
<section id="abstract"><h2>Abstract</h2><p class="abstract">{html.escape(abstract)}</p></section>
<section id="problem"><h2>Introduction / problem statement</h2><p>Content teams can have more pages to inspect than they can review in one cycle. This study supports a narrow operational decision: which sufficiently visible page cohorts might merit a closer CTR and snippet review, after accounting for broad position and content context?</p><p>The analysis does not claim that low CTR proves a page is defective. Search-result layout, query mix, brand demand, seasonality, and user intent can all affect clicks. The ranking is a triage aid for human review, not an instruction to rewrite content automatically.</p></section>
<section id="data"><h2>Data</h2><div class="grid"><div class="stat"><b>{D['row_count']:,}</b><span>anonymized content rows in the public release</span></div><div class="stat"><b>{D['client_count']}</b><span>pseudonymized client groups</span></div><div class="stat"><b>{D['eligible_pages']:,}</b><span>pages with at least {A['min_impressions']} last-window impressions</span></div></div><p>Source: <a href="{D['source_url']}">FlyRank/internship-starter</a>, a public anonymized starter dataset, 30,000 rows and 53 columns. The analysis uses the single content-performance table. It defines the response as clicks divided by impressions in <code>clicks_last_30d</code> and <code>impressions_last_30d</code>; the release also includes previous-30-day and 90-day aggregates.</p><p>The starter dataset card does not state absolute calendar dates for these relative windows. Therefore, the paper reports the window definitions rather than inventing dates. Rows with fewer than 50 latest-window impressions were excluded from model fitting, validation, and ranking to reduce volatility in very low-volume CTR values.</p><div class="callout"><strong>Public-safety choices.</strong> No client or content hashes, titles, URLs, domains, search queries, raw rows, or small-cell breakdowns appear in this paper. Published cohort recommendations require at least 100 eligible pages per group. Raw data is downloaded to a temporary directory at run time and is not in the repository.</div></section>
<section id="method"><h2>Methodology</h2><p>The target is same-window CTR in percentage points. A page is considered eligible at 50 or more impressions. This is a cross-sectional prioritization exercise, not a future-window prediction.</p><h3>Features and exclusions</h3><p>The model uses average position, search volume, competition, word count, content age, days since update, content type, main intent, competition level, age tier, freshness tier, and position tier. Page and client identifiers are not model features. The model excludes clicks, impressions, CTR fields, sessions and engagement metrics, trend variables, product flags, health scores, provider/model metadata, and other outcome-window measures. Categorical values are one-hot encoded; numeric missing values use training-fold medians and categorical missing values use training-fold modes.</p><div class="callout"><strong>Contemporaneous context, not a forecast.</strong> Average position and position tier are snapshot context measures. Their use means the model estimates CTR conditional on observed page context; it does not forecast what will happen after an edit or establish a causal effect.</div><h3>Baseline, model, and validation</h3><p>The baseline predicts each held-out page using the training-fold, impression-weighted mean CTR for its position tier, with the training-fold global mean as a fallback. The comparison model is a random forest (250 trees, minimum leaf size 12, max features 0.8). Training weights are square-root impression weights capped at the training-fold 95th percentile.</p><p>We use five-fold GroupKFold validation, holding all records for each pseudonymized client together. Metrics are pooled out-of-fold and impression-weighted. The primary measure is weighted mean absolute error (MAE), in CTR percentage points; lower is better. All decisions about model fitting and preprocessing are learned within each training fold.</p><h3>Leakage checks</h3><p>Client/content hashes and fields derived directly from clicks, impressions, trends, engagement, or precomputed intervention flags are excluded from features. Position is deliberately retained as contextual information for same-window estimation, so the validation supports association-based triage only. No future labels are available in this starter release; the analysis therefore makes no future-outcome claim.</p></section>
<section id="results"><h2>Results</h2><div class="grid"><div class="stat"><b>{fmt(A['baseline_weighted_mae_pp'], 3)} pp</b><span>position-tier baseline weighted MAE</span></div><div class="stat"><b>{fmt(A['model_weighted_mae_pp'], 3)} pp</b><span>random-forest weighted MAE</span></div><div class="stat"><b>{pct_change}%</b><span>relative MAE reduction versus baseline</span></div></div><p>On pooled out-of-fold predictions, the random forest lowers impression-weighted MAE by {pct_change}% relative to the position-tier baseline. The absolute difference is about {fmt(A['baseline_weighted_mae_pp'] - A['model_weighted_mae_pp'], 3)} percentage points. Fold-level results vary: the model does not improve MAE in every held-out fold. This is a small directional gain, not evidence that a complex model is broadly superior.</p><figure class="figure"><img src="paper/assets/model-vs-baseline.png" alt="Bar chart comparing weighted CTR estimation MAE for model and baseline"><figcaption class="caption">Figure 1. Pooled client-grouped out-of-fold error. Lower MAE is better.</figcaption></figure><figure class="figure"><img src="paper/assets/ctr-by-position.png" alt="Observed CTR by average position tier"><figcaption class="caption">Figure 2. Impression-weighted observed CTR by the dataset’s position tier, restricted to pages with at least 50 latest-window impressions.</figcaption></figure><div class="twocol"><div class="card"><h3>Fold check</h3><p>There are five held-out client folds. The best-performing split does not guarantee performance on a new client or time period. Fold sizes vary because the client groups contain different numbers of eligible pages.</p></div><div class="card"><h3>Overall context</h3><p>Weighted CTR among eligible pages is {fmt(A['overall_weighted_ctr_pct_eligible'], 3)}%. The observed position-tier pattern is descriptive and should not be interpreted as a causal effect of changing position.</p></div></div></section>
<section id="limitations"><h2>Limitations and honest framing</h2><ul class="method-list"><li>The public starter release does not include absolute calendar dates for the latest/previous windows, nor page titles, URLs, or query-level context.</li><li>Low-volume pages are excluded from evaluation, and small recommendation groups are suppressed; results do not describe every page.</li><li>Client-held-out validation reduces client overlap, but there are only 32 pseudonymized client groups and the data is a single snapshot.</li><li>The target and position features describe the same general period. The exercise is not a prospective forecast, controlled experiment, or estimate of impact from a content refresh.</li><li>The improvement over baseline is modest and not uniform across folds. Model residuals may reflect omitted factors rather than fixable content issues.</li><li>The positive click-equivalent gap used to rank cohorts is the out-of-fold expected-versus-observed aggregate difference. It is not an estimate of recoverable clicks, a promised uplift, or a causal effect.</li></ul><p>Interpret all findings as observed associations and prioritization signals. They do not prove how Google ranks pages or that any particular change caused a refresh effect.</p></section>
<section id="recommendations"><h2>Ranked recommendations</h2><p>The table ranks aggregate cohorts by the positive difference between their out-of-fold model-expected clicks and observed clicks. Rates and differences are aggregate-only; a cohort-level discrepancy is a reason to investigate, not proof that its members need edits.</p><div class="table-wrap"><table><thead><tr><th>Content type</th><th>Intent</th><th>Position tier</th><th>Eligible pages</th><th>Observed CTR</th><th>Expected CTR</th><th>Positive gap proxy*</th></tr></thead><tbody>{rows}</tbody></table></div><figure class="figure"><img src="paper/assets/ranked-review-cohorts.png" alt="Ranked aggregate content cohorts by positive model-observed click-equivalent gap"><figcaption class="caption">Figure 3. Largest ranked public-safe cohorts. A larger bar prioritizes review; it does not predict a recoverable result.</figcaption></figure><h3>Action playbook</h3><ol class="method-list"><li><strong>Page 1 cohorts:</strong> audit snippet-to-intent alignment, title/description choices, and competing result formats. Preserve visibility and test controlled changes where practical.</li><li><strong>Pages lower on the results page:</strong> check relevance, coverage, and technical/indexing fundamentals first; a CTR-only edit may not address weak visibility.</li><li><strong>For all groups:</strong> inspect actual examples privately in the authorized analytics environment, verify the underlying query mix, prioritize human review, and record outcomes before scaling changes.</li></ol><p class="small">*“Positive gap proxy” is the cohort’s out-of-fold expected click count minus its observed click count, floored at zero. It is a descriptive ranking statistic—not a causal or guaranteed uplift.</p></section>
<section id="reproducibility"><h2>Reproducibility</h2><p>The pipeline downloads the public starter CSV to <code>/tmp</code>, filters and models the data, then saves only aggregate metrics and charts. To rerun from the repository root:</p><pre class="card"><code>python -m pip install pandas numpy scikit-learn matplotlib
python work/analyze.py
python work/build_paper.py</code></pre><p class="links"><a href="work/capstone.ipynb">Capstone notebook</a><a href="work/analyze.py">Analysis source</a><a href="work/results.json">Aggregate results</a><a href="work/build_paper.py">Paper renderer</a></p><p>The dataset download source and release details are linked above. No credentials or gated warehouse token are required for this public-starter version.</p><h3>Acknowledgments &amp; data credit</h3><p><a href="https://flyrank.ai">Built on the FlyRank ML Internship dataset</a>. Thanks to FlyRank for providing anonymized educational data and the starter workflow.</p><p class="small">References: <a href="https://huggingface.co/datasets/FlyRank/internship-starter">FlyRank Internship Starter Dataset card</a>; <a href="https://github.com/flyrank-bih/flyrank-ml-internship-starter/blob/main/GUIDE.md">FlyRank Internship Starter Guide</a>.</p></section>
<footer>Search Intelligence capstone · Built from a reproducible script and aggregate outputs · Last rendered 17 October 2026.</footer>
</main></body></html>'''
(ROOT / "index.html").write_text(page, encoding="utf-8")
print(f"Rendered {ROOT / 'index.html'} with {len(recs)} recommendation rows.")
